-- ============================================
-- LUMA — Thème 10 : MOYEN 1/3 x4 — Interroger plusieurs suspects et croiser les indices
-- ============================================


update scenarios set content = '{"characters": {"suspect1": "suspect 1", "suspect2": "suspect 2", "suspect3": "suspect 3", "partner": "votre collègue", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "suspect1", "text": "I already told you, I was at home all evening. Ask my neighbor if you don''t believe me.", "text_fr": "Je vous ai déjà dit, j''étais chez moi toute la soirée. Demandez à mon voisin si vous ne me croyez pas.", "choices": [{"text": "What time did you get home exactly?", "text_fr": "À quelle heure êtes-vous rentré exactement ?", "next": "n2"}, {"text": "Did anyone see you enter your home that evening?", "text_fr": "Quelqu''un vous a vu entrer chez vous ce soir-là ?", "next": "n2b"}]}, "n2": {"speaker": "suspect1", "text": "Around 7pm, and I didn''t leave again until the next morning.", "text_fr": "Vers 19h, et je ne suis pas ressorti avant le lendemain matin.", "choices": [{"text": "Thank you, that''s helpful. We''ll follow up with your neighbor.", "text_fr": "Merci, c''est utile. On va vérifier avec votre voisin.", "next": "n3"}]}, "n2b": {"speaker": "suspect1", "text": "My neighbor might have, we sometimes wave when I get home.", "text_fr": "Mon voisin a peut-être vu, on se salue parfois quand je rentre.", "choices": [{"text": "We''ll check with them. Thank you for your time.", "text_fr": "On va vérifier avec eux. Merci pour votre temps.", "next": "n3"}]}, "n3": {"speaker": "narrator", "text": "(Second interview — a nervous suspect fidgets in their chair.)", "text_fr": "(Deuxième interrogatoire — un suspect nerveux se tortille sur sa chaise.)", "choices": [{"text": "Can you tell me where you were on the night of the break-in?", "text_fr": "Vous pouvez me dire où vous étiez le soir du cambriolage ?", "next": "n4"}]}, "n4": {"speaker": "suspect2", "text": "I— I was at a friend''s place, playing cards. Left around... 10pm, I think?", "text_fr": "J''étais— j''étais chez un ami, en train de jouer aux cartes. Parti vers... 22h, je crois ?", "choices": [{"text": "You seem uncertain about the time. Can you clarify?", "text_fr": "Vous semblez incertain sur l''heure. Vous pouvez clarifier ?", "next": "n5"}, {"text": "Which friend, and can they confirm this?", "text_fr": "Quel ami, et il peut confirmer ça ?", "next": "n5b"}]}, "n5": {"speaker": "suspect2", "text": "(Avoids eye contact) I mean, it could''ve been 9, honestly I wasn''t watching the clock.", "text_fr": "(Évite le contact visuel) Enfin, ça aurait pu être 21h, honnêtement je regardais pas l''heure.", "choices": [{"text": "That''s a pretty big window of uncertainty. Anything else you remember?", "text_fr": "C''est une grande fenêtre d''incertitude. Autre chose dont vous vous souvenez ?", "next": "n6"}]}, "n5b": {"speaker": "suspect2", "text": "His name is... Marcus. Yeah, Marcus. He can confirm, probably.", "text_fr": "Son nom c''est... Marcus. Ouais, Marcus. Il peut confirmer, probablement.", "choices": [{"text": "''Probably'' is an odd word to use. Is there a reason for that hesitation?", "text_fr": "''Probablement'' c''est un mot bizarre à utiliser. Il y a une raison à cette hésitation ?", "next": "n6"}]}, "n6": {"speaker": "suspect2", "text": "(Sweating slightly) No reason, I just... wasn''t paying close attention that night.", "text_fr": "(Transpire légèrement) Aucune raison, j''étais juste... pas très attentif ce soir-là.", "choices": [{"text": "Third interview — let''s compare notes with what we''ve gathered.", "text_fr": "Troisième interrogatoire — comparons les notes avec ce qu''on a recueilli.", "next": "n7"}]}, "n7": {"speaker": "suspect3", "text": "I''ve got nothing to hide. I was working late at the office, my badge log can confirm it.", "text_fr": "J''ai rien à cacher. Je travaillais tard au bureau, mon badge peut le confirmer.", "choices": [{"text": "That''s easily verifiable. What time did you leave?", "text_fr": "C''est facilement vérifiable. Vous êtes parti à quelle heure ?", "next": "n8"}]}, "n8": {"speaker": "suspect3", "text": "Around 11pm. Security can confirm, there are cameras at the entrance.", "text_fr": "Vers 23h. La sécurité peut confirmer, il y a des caméras à l''entrée.", "choices": [{"text": "That''s very specific and verifiable — thank you.", "text_fr": "C''est très précis et vérifiable — merci.", "next": "n9"}]}, "n9": {"speaker": "partner", "text": "So, comparing all three — suspect two''s story has the most holes. Nervous, vague on timing.", "text_fr": "Alors, en comparant les trois — l''histoire du suspect deux a le plus de trous. Nerveux, vague sur l''heure.", "choices": [{"text": "Agreed. Let''s verify his alibi with Marcus directly, and press further if it doesn''t hold up.", "text_fr": "D''accord. Vérifions son alibi directement avec Marcus, et insistons si ça ne tient pas.", "next": "end_crossed"}]}, "end_crossed": {"speaker": "partner", "text": "Good instinct. Cross-referencing these alibis just gave us our prime suspect.", "text_fr": "Bon instinct. Croiser ces alibis vient de nous donner notre suspect principal.", "end": true, "ending_label": "Incohérences repérées entre les témoignages 🕵️🔗"}}}'::jsonb, is_playable = true
where title = 'Interroger plusieurs suspects et croiser les indices'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
